param([ValidateSet('build','real0','real4','provider')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-matrix-algorithm-20260914';$seed='D:\projects\AIMA-public-matrix-producer-choices-20260914-r3';$source='c16219f0ad9effee402405ed3bfc494a2fa2d144';$bundle='D:\projects\matrix-algorithm-c16219f.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '9945de757dfd9117f246c4f2f6c17457379d1b95285ccef1a6093ff29df6f199'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $source;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $source -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\matrix-algorithm-safety';$exe=Join-Path $build 'qrt-projection-safety.exe';$provider=Join-Path $repo 'build\matrix-algorithm-provider'
$out=Join-Path $repo ('build\matrix-algorithm-'+$Action+'-r1');$specPath=Join-Path $repo ('build\matrix-algorithm-'+$Action+'-r1.json')
foreach($p in @($out,$specPath)){if(Test-Path $p){throw 'Evidence exists'}}
$null=New-Item -ItemType Directory -Path (Join-Path $repo 'build') -Force
$sourceFiles=@('native\providers\whole_provider.cpp','native\providers\q8192_matrix_producer_policy.h','tests\native\projection_safety_selftest.cpp','scripts\baiying_build_whole_provider.ps1')
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName.Substring($repo.Length+1)})
}
$sourceInputs=@();foreach($file in ($sourceFiles|Sort-Object -Unique)){$sourceInputs+=@{file=$file;sha256=(Get-FileHash (Join-Path $repo $file) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$source;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; native compile';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;replay_lanes=4;purpose='Opt-in algorithm4 for four complete q8192 FP32-output projection shapes, prewarmed at load. All original correction arithmetic, PPB1000 and midpoint512 retained. Captured projection keeps7169 original rows and repeats the first1023 inputs with their independent GB10 outputs for q8192-only dispatch; reference is never a compute input.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$env:QRT_QWEN36_PROFILE_MATRIX_PRODUCER_WALL='0';$env:QRT_QWEN36_PREFILL_HIPBLASLT_PRODUCER='1';$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_ALGORITHM=if($Action -eq 'real4'){'4'}else{'0'}
$env:QRT_QWEN36_HAWKEYE_DEVICE_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_PREPARED_OPERANDS='1';$env:QRT_QWEN36_HAWKEYE_PREVALIDATED_FLOAT_REPLAY='1';$env:QRT_QWEN36_HAWKEYE_PARTITION_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_BOUND='0';$env:QRT_QWEN36_HAWKEYE_PREPARED_K16_MAJOR='0';$env:QRT_QWEN36_HAWKEYE_FLOAT_REPLAY='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_AUDIT='0';$env:QRT_QWEN36_HAWKEYE_ABSOLUTE_PRODUCT_HIPBLASLT='0';$env:QRT_QWEN36_HAWKEYE_PACKED_CANDIDATES='0';$env:QRT_QWEN36_HAWKEYE_CORRECTION_MAXIMUM_BLOCKS_PER_LAUNCH='4096'
foreach($name in @('SCALAR','TILED','BOUNDED','SCALED','ROW_MAX','F32_CARRY','RANGE','PARTITION','INTERVAL')){[Environment]::SetEnvironmentVariable('QRT_PROJECTION_SAFETY_'+$name+'_REPLAY','0','Process')}
$spec.matrix_producer_algorithm=[int]$env:QRT_QWEN36_Q8192_MATRIX_PRODUCER_ALGORITHM
function Check-Run([string]$action){
 $path=Join-Path $repo ('build\matrix-algorithm-'+$action+'-r1\run-record.json');$r=[IO.File]::ReadAllText($path)|ConvertFrom-Json
 if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('Incomplete prerequisite '+$action)}
 return (Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()
}
if($Action -in @('build','provider')){
 $target=if($Action -eq 'build'){$build}else{$provider};if(Test-Path $target){throw 'Build exists'}
 if($Action -eq 'provider'){$spec.prerequisite_runs=@((Check-Run 'real0'),(Check-Run 'real4'))}
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$target,'-DppReduction','1','-CompactNormalize','1','-HawkeyeReplayLanes','4','-CompileTimeoutSeconds','240');$timeout=270
 if($Action -eq 'build'){$spec.arguments+=@('-ProjectionSafetyTest')}
}else{
 $spec.build_run_sha256=Check-Run 'build'
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 $artifact=@($meta.artifacts|Where-Object {$_.name -eq 'qrt-projection-safety.exe'})
 if($meta.repo_commit -ne $source -or $meta.dirty_tree -or $artifact.Count -ne 1 -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact[0].sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $inputTensor='D:\projects\AIMA-public-exact-ab-20260910\build\fla-model-q7169-embeddingnorm-capture-r1\input-rmsnorm-bf16.bin';$weightTensor='D:\projects\AIMA-public-capture-20260910\build\layer0-weights-r1\qkv.bin';$referenceTensor='D:\projects\sm121-qkv-reference-9510d980.bin'
 $tensors=@(@{path=$inputTensor;sha256='6c67321f81040780088a742070c48ab3023043b8ef9de71d1ed5a970a8fe9161'},@{path=$weightTensor;sha256='b06edcc9973be74f862d072f89a195e2eecea067ee615144be8510656122401f'},@{path=$referenceTensor;sha256='9510d98057e047e7dd6f4e7b9b6010862e54e938d37bb854078c2de419f0bf37'})
 foreach($tensor in $tensors){if((Get-FileHash $tensor.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $tensor.sha256){throw 'Original QKV tensor changed'}}
 $spec.executable=$exe;$spec.arguments=@('--real-qkv-q8192',$inputTensor,$weightTensor,$referenceTensor,'1000');$spec.tensor_inputs=$tensors
 $spec.model='D:\models\Qwen3.6-35B-A3B; original captured layer-zero QKV and independently comparable repeated rows';$spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83';$spec.gb10_reference_host='aitopatom-66c4';$spec.gb10_capture_sha256='5522ec3e4725adf459e505dff61aa3981a08b416b7b2bfe40e929ccf250b4d8b';$spec.prompt_sha256='26515be92b5563d921bade3ed6673ffe9e0c6560fbd7d78f587a0400da802804';$spec.reference_is_compute_input=$false;$spec.selector_error_bound_ppb=1000;$spec.tokens=8192;$spec.source_tokens=7169;$spec.repeated_input_rows=1023;$timeout=120
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native matrix algorithm action failed'}
if($Action -in @('real0','real4')){
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $result=@($reports|Where-Object {$_.type -eq 'real_qkv_result'});$summary=@($reports|Where-Object {$_.type -eq 'summary'})
 if($summary.Count -ne 1 -or $summary[0].status -ne 'pass' -or $summary[0].gpu_cases -ne 1 -or $result.Count -ne 1 -or $result[0].elements -ne 67108864 -or $result[0].bf16_mismatches -ne 0 -or -not $result[0].redzones_pass -or -not $result[0].inputs_immutable){throw 'Captured QKV mismatch'}
 $markers=@([IO.File]::ReadAllLines((Join-Path $out 'product.stderr.log'))|Where-Object {$_.StartsWith('BATCH_MARK q8192_matrix_producer_algorithm ')})
 if($markers.Count -ne 1 -or $markers[0] -notmatch ('heuristic_index='+$spec.matrix_producer_algorithm+' ')){throw 'Algorithm dispatch marker mismatch'}
}
